```python
import os
import logging
import json
import time
import re
import uuid
import threading
import random
import concurrent.futures
from datetime import datetime
from functools import wraps

import requests
from flask import Flask, request, jsonify, send_file
from flask_cors import CORS

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

app = Flask(__name__)
CORS(app)

XAI_API_KEY = os.environ.get('XAI_API_KEY', '')
EXA_API_KEY = os.environ.get('EXA_API_KEY', '')
CEREBRAS_API_KEY = os.environ.get('CEREBRAS_API_KEY', '')

XAI_BASE_URL = ""
EXA_BASE_URL = ""
CEREBRAS_BASE_URL = ""

research_tasks = {}
research_lock = threading.Lock()
TASK_EXPIRY_SECONDS = 3600


def validate_api_key(key: str, service: str) -> bool:
    if not key:
        raise ValueError(f"{service} API key is required but not configured.")
    return True


def retry_on_rate_limit(max_retries: int = 5, base_backoff: float = 1.0):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            last_error = None
            for attempt in range(max_retries):
                try:
                    return func(*args, **kwargs)
                except requests.exceptions.HTTPError as e:
                    last_error = e
                    status = getattr(e.response, "status_code", None)
                    if status == 429 and attempt < max_retries - 1:
                        wait_time = base_backoff * (2 ** attempt) + random.uniform(0, 0.5)
                        logger.warning(f"Rate limit for {func.__name__}; retry {attempt + 1}/{max_retries} after {wait_time:.2f}s")
                        time.sleep(wait_time)
                        continue
                    raise
                except requests.exceptions.RequestException as e:
                    last_error = e
                    if attempt < max_retries - 1:
                        wait_time = base_backoff * (2 ** attempt) + random.uniform(0, 0.5)
                        logger.warning(f"Network error in {func.__name__}; retry {attempt + 1}/{max_retries} after {wait_time:.2f}s: {e}")
                        time.sleep(wait_time)
                        continue
                    raise Exception(f"Max retries exceeded for {func.__name__}") from last_error
            raise Exception(f"Max retries exceeded for {func.__name__}") from last_error
        return wrapper
    return decorator


class GrokAgent:
    def __init__(self):
        validate_api_key(XAI_API_KEY, "xAI")
        self.model = "grok-beta"
        self.headers = {
            "Authorization": f"Bearer {XAI_API_KEY}",
            "Content-Type": "application/json"
        }

    @retry_on_rate_limit()
    def chat(self, messages, temperature: float = 0.07, max_tokens: int = 32768, timeout: int = 180):
        url = f"{XAI_BASE_URL}/chat/completions"
        payload = {
            "model": self.model,
            "messages": messages,
            "temperature": temperature,
            "max_tokens": max_tokens
        }
        resp = requests.post(url, headers=self.headers, json=payload, timeout=timeout)
        resp.raise_for_status()
        return resp.json()


class GrokFastDocumentProcessor:
    def __init__(self):
        validate_api_key(XAI_API_KEY, "xAI")
        self.model = "grok-beta"
        self.headers = {
            "Authorization": f"Bearer {XAI_API_KEY}",
            "Content-Type": "application/json"
        }

    @retry_on_rate_limit()
    def process_large_document(self, document_content: str, user_query: str, timeout: int = 300) -> str:
        url = f"{XAI_BASE_URL}/chat/completions"
        system_prompt = f"""You are a professional document analyst.
Your task: Comprehensive analysis and structured summary of a large document.
User query: {user_query}
Create a detailed, structured summary from the document that:
1. Highlights information relevant to the user's query
2. Breaks content into logical sections
3. Preserves key details and context
4. Is shorter and more readable than the original
Format: Markdown, divided into chapters."""
        messages = [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": f"Document content:\n\n{document_content}"}
        ]
        payload = {
            "model": self.model,
            "messages": messages,
            "temperature": 0.3,
            "max_tokens": 32768
        }
        resp = requests.post(url, headers=self.headers, json=payload, timeout=timeout)
        resp.raise_for_status()
        data = resp.json()
        return data["choices"][0]["message"]["content"]


class ExaResearchAgent:
    def __init__(self):
        validate_api_key(EXA_API_KEY, "Exa")
        self.headers = {
            "x-api-key": EXA_API_KEY,
            "Content-Type": "application/json"
        }

    @retry_on_rate_limit()
    def search(
        self,
        query: str,
        num_results: int = 100,
        use_autoprompt: bool = True,
        start_published_date: str = None,
        end_published_date: str = None,
        include_domains=None,
        exclude_domains=None,
        timeout: int = 120
    ):
        url = f"{EXA_BASE_URL}/search"
        payload = {
            "query": query,
            "numResults": num_results,
            "useAutoprompt": use_autoprompt
        }
        if start_published_date:
            payload["startPublishedDate"] = start_published_date
        if end_published_date:
            payload["endPublishedDate"] = end_published_date
        if include_domains:
            payload["includeDomains"] = include_domains
        if exclude_domains:
            payload["excludeDomains"] = exclude_domains
        resp = requests.post(url, headers=self.headers, json=payload, timeout=timeout)
        resp.raise_for_status()
        return resp.json()

    @retry_on_rate_limit()
    def get_contents(self, ids, text: bool = False, highlights: bool = True, timeout: int = 180):
        url = f"{EXA_BASE_URL}/contents"
        highlights_param = {"numSentences": 20, "highlightsPerUrl": 3} if highlights else False
        payload = {"ids": ids, "text": text, "highlights": highlights_param}
        resp = requests.post(url, headers=self.headers, json=payload, timeout=timeout)
        resp.raise_for_status()
        return resp.json()


class ResearchOrchestrator:
    def __init__(self):
        self.grok = GrokAgent()
        self.grok_fast = GrokFastDocumentProcessor()
        self.exa = ExaResearchAgent()

    def execute_research(self, task_id: str, user_query: str, attached_file_content: str = None, options: dict = None):
        max_sources = options.get("max_sources", 100) if options else 100
        if len(user_query) > 5000:
            raise ValueError("User query too long; max 5000 characters.")
        try:
            with research_lock:
                research_tasks[task_id]["status"] = "planning"
                research_tasks[task_id]["progress"] = 10

            processed_document = None
            if attached_file_content and len(attached_file_content) > 50000:
                logger.info("Large document detected - processing with Grok Fast...")
                processed_document = self.grok_fast.process_large_document(attached_file_content, user_query)

            document_info = f"Attached document content (processed if large):\n\n{processed_document if processed_document else attached_file_content if attached_file_content else 'None'}"

            planning_messages = [
                {
                    "role": "system",
                    "content": """You are the Grok main agent. Your task is to prepare a comprehensive research plan.
Analyze the user's query and determine:
1. What Exa searches to perform (search queries)
2. What time range to investigate
3. What domains to include/exclude
4. How many sources to collect
5. What content analyses to perform
Return in JSON format:
{
"analysis": "brief analysis",
"search_queries": ["query1", "query2", ...],
"num_results_per_query": 50,
"date_range": {"start": "YYYY-MM-DD", "end": "YYYY-MM-DD"},
"domains": {"include": [], "exclude": []},
"research_steps": ["step1", "step2", ...]
}"""
                },
                {
                    "role": "user",
                    "content": f"""Research question: {user_query}

{document_info}

{f"User options: {json.dumps(options, ensure_ascii=False)}" if options else ""}
Prepare the research plan!"""
                }
            ]
            plan_response = self.grok.chat(planning_messages, temperature=0.07, max_tokens=8192)
            research_plan = self._extract_json(plan_response["choices"][0]["message"]["content"])
            search_queries = research_plan.get("search_queries", [user_query])
            num_queries = len(search_queries)
            query_progress_increment = 30.0 / max(1, num_queries)
            search_progress_increment = 100.0 / max(1, num_queries)

            with research_lock:
                research_tasks[task_id]["status"] = "searching"
                research_tasks[task_id]["progress"] = 30
                research_tasks[task_id]["sub_agents"] = [
                    {"name": "Grok Orchestrator", "status": "Research plan prepared", "progress": 100},
                    {"name": "Exa Neural Search", "status": "Collecting sources", "progress": 0},
                    {"name": "Content Analyzer", "status": "Waiting", "progress": 0},
                    {"name": "Report Generator", "status": "Waiting", "progress": 0}
                ]

            logger.info("Executing Exa AI research...")
            all_results = []
            seen_ids = set()

            def perform_search(q):
                return self.exa.search(
                    query=q,
                    num_results=research_plan.get("num_results_per_query", 50),
                    start_published_date=research_plan.get("date_range", {}).get("start"),
                    end_published_date=research_plan.get("date_range", {}).get("end"),
                    include_domains=research_plan.get("domains", {}).get("include"),
                    exclude_domains=research_plan.get("domains", {}).get("exclude"),
                )

            with concurrent.futures.ThreadPoolExecutor(max_workers=min(max(1, num_queries), 5)) as executor:
                future_to_query = {executor.submit(perform_search, q): q for q in search_queries}
                for idx, future in enumerate(concurrent.futures.as_completed(future_to_query)):
                    try:
                        search_results = future.result()
                        for res in search_results.get("results", []):
                            rid = res.get("id")
                            if rid and rid not in seen_ids:
                                seen_ids.add(rid)
                                all_results.append(res)
                    except Exception as e:
                        logger.error(f"Search error for query {future_to_query[future]}: {e}")

                    current_search_progress = min(int((idx + 1) * search_progress_increment), 100)
                    current_overall_progress = 30 + int((idx + 1) * query_progress_increment)
                    with research_lock:
                        research_tasks[task_id]["sub_agents"][1]["progress"] = current_search_progress
                        research_tasks[task_id]["progress"] = min(current_overall_progress, 60)

            all_results.sort(key=lambda x: x.get("score", 0), reverse=True)
            if max_sources and max_sources > 0:
                all_results = all_results[:max_sources]

            with research_lock:
                research_tasks[task_id]["status"] = "analyzing"
                research_tasks[task_id]["progress"] = 60
                research_tasks[task_id]["sub_agents"][2]["status"] = "Analyzing content"
                research_tasks[task_id]["sub_agents"][2]["progress"] = 50

            logger.info(f"Downloading content for {len(all_results)} sources...")
            ids = [r["id"] for r in all_results if "id" in r]
            contents = self.exa.get_contents(ids)
            contents_data = contents.get("contents", {}) if isinstance(contents, dict) else {}

            summarized_contents = {}
            for id_ in ids:
                content = contents_data.get(id_, {}) if isinstance(contents_data, dict) else {}
                hl = content.get("highlights", {})
                hls = hl.get("highlights", []) if isinstance(hl, dict) else []
                summary = "\n\n".join(hls) if isinstance(hls, list) else ""
                summarized_contents[id_] = {"summary": summary, "highlights": hls}

            with research_lock:
                research_tasks[task_id]["sources"] = all_results
                research_tasks[task_id]["sub_agents"][2]["progress"] = 100
                research_tasks[task_id]["progress"] = 75
                research_tasks[task_id]["status"] = "generating_report"
                research_tasks[task_id]["sub_agents"][3]["status"] = "Generating report"
                research_tasks[task_id]["sub_agents"][3]["progress"] = 50

            document_synthesis_info = f"Attached document content (processed if large):\n\n{processed_document if processed_document else attached_file_content if attached_file_content else ''}"
            synthesis_messages = [
                {
                    "role": "system",
                    "content": """You are the Grok main agent. Prepare a detailed, comprehensive research report.
The report should include:
1. Executive Summary
2. Methodology (what sources were used)
3. Key Findings (divided into sections)
4. Conclusions
5. Sources list
Format: Markdown, professional style, detailed."""
                },
                {
                    "role": "user",
                    "content": f"""Research question: {user_query}
Research plan:
{json.dumps(research_plan, indent=2, ensure_ascii=False)}
Sources found: {len(all_results)}
Contents (summaries and highlights):
{json.dumps(summarized_contents, indent=2, ensure_ascii=False)}
{document_synthesis_info}
Prepare the final report!"""
                }
            ]

            final_response = self.grok.chat(synthesis_messages, temperature=0.07, max_tokens=32768)
            final_report = final_response["choices"][0]["message"]["content"]

            with research_lock:
                research_tasks[task_id]["status"] = "completed"
                research_tasks[task_id]["progress"] = 100
                research_tasks[task_id]["report"] = final_report
                research_tasks[task_id]["sub_agents"][3]["progress"] = 100
                research_tasks[task_id]["sub_agents"][3]["status"] = "Report completed"

            return {
                "success": True,
                "research_plan": research_plan,
                "sources_found": len(all_results),
                "sources": all_results,
                "report": final_report,
                "processed_document_summary": processed_document if processed_document else None
            }
        except Exception as e:
            logger.error(f"Research error for task {task_id}: {e}", exc_info=True)
            with research_lock:
                if task_id in research_tasks:
                    research_tasks[task_id]["status"] = "error"
                    research_tasks[task_id]["error"] = str(e)
            return {"success": False, "error": str(e)}

    def _extract_json(self, text: str):
        text = (text or "").strip()
        if not text:
            return {}
        try:
            return json.loads(text)
        except json.JSONDecodeError:
            pass
        fence = re.search(r"``````", text, re.DOTALL)
        if fence:
            try:
                return json.loads(fence.group(1))
            except json.JSONDecodeError:
                pass
        brace_count = 0
        start = -1
        for i, ch in enumerate(text):
            if ch == "{":
                if brace_count == 0:
                    start = i
                brace_count += 1
            elif ch == "}":
                brace_count -= 1
                if brace_count == 0 and start != -1:
                    candidate = text[start:i + 1]
                    try:
                        return json.loads(candidate)
                    except json.JSONDecodeError:
                        start = -1
                        continue
        return {}


def cleanup_expired_tasks():
    try:
        with research_lock:
            expired = []
            now = datetime.utcnow()
            for tid, task in list(research_tasks.items()):
                created_at = task.get("created_at")
                if not created_at:
                    continue
                try:
                    dt = datetime.fromisoformat(created_at)
                except Exception:
                    continue
                if (now - dt).total_seconds() > TASK_EXPIRY_SECONDS:
                    expired.append(tid)
            for tid in expired:
                del research_tasks[tid]
    finally:
        t = threading.Timer(300, cleanup_expired_tasks)
        t.daemon = True
        t.start()


orchestrator = ResearchOrchestrator()
cleanup_expired_tasks()


@app.route('/api/research/create', methods=['POST'])
def create_research():
    try:
        if request.content_type and 'multipart/form-data' in request.content_type:
            user_query = (request.form.get('goal', '') or '').strip()
            max_sources = int(request.form.get('max_sources', 100))
        else:
            data = request.json or {}
            user_query = (data.get('goal', '') or '').strip()
            max_sources = int(data.get('max_sources', 100))
        if not user_query:
            return jsonify({"error": "Goal is required"}), 400

        attached_file_content = None
        if 'file' in request.files and request.files['file'].filename:
            file = request.files['file']
            try:
                attached_file_content = file.read().decode('utf-8', errors='ignore')
            except Exception as e:
                logger.error(f"Error reading uploaded file: {e}")
                return jsonify({"error": "Failed to read uploaded file"}), 400

        task_id = str(uuid.uuid4())
        with research_lock:
            research_tasks[task_id] = {
                "id": task_id,
                "goal": user_query,
                "status": "starting",
                "progress": 0,
                "sub_agents": [],
                "sources": [],
                "report": "",
                "updates": [],
                "error": None,
                "created_at": datetime.utcnow().isoformat()
            }

        def run_research():
            try:
                orchestrator.execute_research(
                    task_id=task_id,
                    user_query=user_query,
                    attached_file_content=attached_file_content,
                    options={"max_sources": max_sources}
                )
                logger.info(f"Research {task_id} completed")
            except Exception as e:
                logger.error(f"Thread error for {task_id}: {e}", exc_info=True)
                with research_lock:
                    if task_id in research_tasks:
                        research_tasks[task_id]["status"] = "error"
                        research_tasks[task_id]["error"] = str(e)

        thread = threading.Thread(target=run_research, name=f"research-{task_id}", daemon=True)
        thread.start()
        return jsonify({"task_id": task_id}), 201
    except Exception as e:
        logger.error(f"Create research error: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route('/api/research/<task_id>', methods=['GET'])
def get_research_status(task_id):
    try:
        with research_lock:
            task = research_tasks.get(task_id)
            if not task:
                return jsonify({"error": "Task not found"}), 404
            task_copy = dict(task)
            task_copy['updates'] = task_copy.get('updates', [])
        return jsonify({
            "task_id": task_id,
            "status": task_copy['status'],
            "progress": task_copy['progress'],
            "sub_agents": task_copy['sub_agents'],
            "sources": task_copy['sources'],
            "report": task_copy['report'],
            "updates": task_copy['updates'],
            "error": task_copy['error']
        })
    except Exception as e:
        logger.error(f"Get research status error: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route('/api/research/<task_id>/update', methods=['POST'])
def update_research(task_id):
    try:
        data = request.json or {}
        instructions = (data.get('instructions', '') or '').strip()
        if not instructions:
            return jsonify({"error": "Instructions are required"}), 400
        with research_lock:
            task = research_tasks.get(task_id)
            if not task:
                return jsonify({"error": "Task not found"}), 404
            if 'updates' not in task or not isinstance(task['updates'], list):
                task['updates'] = []
            task['updates'].append({"instructions": instructions, "timestamp": datetime.utcnow().isoformat()})
        logger.info(f"Update received for task {task_id}")
        return jsonify({"success": True, "message": "Research update received and stored"})
    except Exception as e:
        logger.error(f"Update research error: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route('/api/chat', methods=['POST'])
def chat():
    try:
        validate_api_key(CEREBRAS_API_KEY, "Cerebras")
        data = request.json or {}
        messages = data.get('messages', [])
        if not messages:
            return jsonify({"error": "Messages are required"}), 400

        @retry_on_rate_limit()
        def make_cerebras_call():
            headers = {"Authorization": f"Bearer {CEREBRAS_API_KEY}", "Content-Type": "application/json"}
            payload = {"model": "gpt-oss-120b", "messages": messages, "temperature": 0.07, "max_tokens": 65000}
            resp = requests.post(f"{CEREBRAS_BASE_URL}/chat/completions", headers=headers, json=payload, timeout=180)
            resp.raise_for_status()
            return resp.json()

        result = make_cerebras_call()
        return jsonify(result)
    except Exception as e:
        logger.error(f"Chat error: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route('/api/health', methods=['GET'])
def health():
    xai_configured = False
    exa_configured = False
    cerebras_configured = False
    try:
        validate_api_key(XAI_API_KEY, "xAI")
        xai_configured = True
    except ValueError:
        pass
    try:
        validate_api_key(EXA_API_KEY, "Exa")
        exa_configured = True
    except ValueError:
        pass
    try:
        validate_api_key(CEREBRAS_API_KEY, "Cerebras")
        cerebras_configured = True
    except ValueError:
        pass
    with research_lock:
        active_tasks = sum(1 for task in research_tasks.values() if task.get("status") not in ["completed", "error"])
    return jsonify({
        "status": "healthy",
        "exa_configured": exa_configured,
        "xai_configured": xai_configured,
        "cerebras_configured": cerebras_configured,
        "active_tasks": active_tasks
    })


@app.route('/')
def index():
    return send_file('index.html')


if __name__ == '__main__':
